mapper.select:
SELECT id, tenant_id, stat_date, process_def_key, process_def_name, total_count, completed_count, failed_count, timeout_count, timeout_count AS timeout_event_count, timeout_instance_count, anomaly_count, anomaly_count AS anomaly_event_count, anomaly_instance_count, avg_duration AS avg_duration_ms, min_duration AS min_duration_ms, max_duration AS max_duration_ms, create_time, update_time, CASE WHEN total_count > 0 THEN ROUND((completed_count * 100.0 / total_count), 2) ELSE 0 END AS success_rate, CASE WHEN total_count > 0 THEN ROUND((failed_count * 100.0 / total_count), 2) ELSE 0 END AS failed_rate, CASE WHEN total_count > 0 THEN ROUND((timeout_instance_count * 100.0 / total_count), 2) ELSE 0 END AS timeout_rate, CASE WHEN total_count > 0 THEN ROUND((timeout_instance_count * 100.0 / total_count), 2) ELSE 0 END AS timeout_instance_rate, CASE WHEN total_count > 0 THEN ROUND((anomaly_instance_count * 100.0 / total_count), 2) ELSE 0 END AS anomaly_rate, CASE WHEN total_count > 0 THEN ROUND((anomaly_instance_count * 100.0 / total_count), 2) ELSE 0 END AS anomaly_instance_rate, CASE WHEN total_count > 0 THEN ROUND(((failed_count + timeout_instance_count + anomaly_instance_count) * 100.0 / total_count), 2) ELSE 0 END AS risk_score FROM wf_performance_stats
tenant_id = #{tenantId}
AND stat_date >= #{startDate}
AND stat_date <= #{endDate}
AND process_def_key = #{processDefKey}
ORDER BY stat_date ASC, process_def_name ASC, process_def_key ASC
